#include "RigidBody.h"
// Observer-only unchanged M77 corrective-step fixture and control intent.
#define main original_m77_controller_main
#include "../../../../tests/PhysicalBalanceControllerTests.cpp"
#undef main
int main(){double peakRelativeDriftEnergy=0,peakAbsoluteDriftEnergy=0;int peakAt=-1;Fixture f(0,glm::quat(1,0,0,0),true,false,true);f.Advance(120,false);f.controller.Request(f.world,BalanceTask::Stand,true,true,f.error);f.Advance(360);f.world.ApplyLinearImpulse(f.mapping[0].body,{0,0,29});auto prior=f.controller.History();for(int k=0;k<720;++k){for(auto& b:f.mapping){RigidBody rb;auto pose=f.world.GetTransform(b.body);rb.inverseMass=1.f/f.world.GetMass(b.body);rb.orientation=pose.rotation;rb.angularVelocity=f.world.GetAngularVelocity(b.body);auto R=glm::mat3_cast(glm::normalize(rb.orientation));rb.inverseInertiaLocal=glm::transpose(R)*glm::inverse(f.world.GetInertiaWorld(b.body))*R;auto energy=[&]{auto Q=glm::dmat3(glm::mat3_cast(glm::normalize(rb.orientation)));auto I=Q*glm::inverse(glm::dmat3(rb.inverseInertiaLocal))*glm::transpose(Q);return .5*glm::dot(glm::dvec3(rb.angularVelocity),I*glm::dvec3(rb.angularVelocity));};double before=energy();IntegrateRigidBodyPosition(rb,1.f/60);double error=std::abs(energy()-before);if(error>peakAbsoluteDriftEnergy){peakAbsoluteDriftEnergy=error;peakAt=k;}if(before>1e-6)peakRelativeDriftEnergy=std::max(peakRelativeDriftEnergy,error/before);}f.Advance(1);auto& h=f.controller.History();auto& o=f.controller.Observation();if(k%20==0||h.reason!=prior.reason||h.swing!=prior.swing||h.landings!=prior.landings){auto p=f.world.GetTransform(f.mapping[0].body);std::printf("step=%d progress=%d swing=%d last=%d landings=%u rootY=%.8f upright=%.8f speed=%.8f contacts=%u/%u reason=%s\n",k,int(h.progress),h.swing,h.lastSwing,h.landings,p.position.y,o.upright,o.speed,o.supports[0].contacts,o.supports[1].contacts,h.reason.c_str());}prior=h;}std::printf("Independent copied free-drift peak energy error relative %.9g absolute %.9g J at step %d; not global constraint energy accounting\n",peakRelativeDriftEnergy,peakAbsoluteDriftEnergy,peakAt);return f.Standing()?0:1;}
